WHERE {
  # Count total halts per route
  {
    SELECT ?route (COUNT(?stopEvent) AS ?totalHalts)
    WHERE {
      ?trip a tro:Trip .
      ?trip tro:line ?line .
      ?line a tro:Line .
      ?stopEvent a tro:StopEvent .
      ?stopEvent tro:journey ?trip .
      BIND(?line AS ?route)
    }
    GROUP BY ?route
  }

  # Count trips per route
  {
    SELECT ?route (COUNT(?trip) AS ?tripCount)
    WHERE {
      ?trip a tro:Trip .
      ?trip tro:line ?line .
      ?line a tro:Line .
      BIND(?line AS ?route)
    }
    GROUP BY ?route
  }

  # Calculate mean halts per trip
  BIND((?totalHalts / ?tripCount) AS ?meanHaltsPerTrip)
}

